import{internalAccount,heatingAt,experimentResult,toy,compressedPressure}from './mat2-models.js?v=20261023-physicscomplete01';
const ink='#faf5ed',mint='#aacdc2',coral='#f18d77',dim='#afc0cd';const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=x=>Number(Number(x).toFixed(3));
const T=(x,y,s,n=18,c=ink)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;const L=(x,y,u,v,c=dim,w=3)=>`<path d="M${x} ${y}L${u} ${v}" fill="none" stroke="${c}" stroke-width="${w}"/>`;const B=(x,y,w,h,c='#25475b')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${c}" stroke="${dim}"/>`;const ball=(x,y,r=10)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="url(#mat2-ball)" stroke="#d9e8e8"/>`;
export const thermalSVG=(body,label)=>`<svg viewBox="0 0 560 480" role="img" aria-label="${esc(label)}"><defs><radialGradient id="mat2-ball" cx="28%" cy="22%"><stop stop-color="#effffb"/><stop offset=".48" stop-color="#a2c9c0"/><stop offset="1" stop-color="#4b737d"/></radialGradient></defs>${body}</svg>`;
const arrow=(x,y,u,v,c=coral)=>{let a=Math.atan2(v-y,u-x),h=10;return L(x,y,u,v,c)+`<path d="M${u-h*Math.cos(a-.45)} ${v-h*Math.sin(a-.45)}L${u} ${v}L${u-h*Math.cos(a+.45)} ${v-h*Math.sin(a+.45)}" fill="none" stroke="${c}" stroke-width="3"/>`;};
export function internalFigure({a='warm',b='40',progress=1,movie=false,revealed=true,state='0'}={}){let mode=movie?(progress<.5?'warm':'melt'):a,input=movie?80*(progress<.5?progress*2:(progress-.5)*2):+b,r=internalAccount(mode,input),body=T(280,29,'Internal energy = kinetic + potential',24)+T(280,64,mode==='warm'?'Single phase: temperature rises':'Melting: temperature held constant',21)+B(45,108,470,135,'#1b394e');
for(let j=0;j<12;j++){let x=89+(j%6)*75,y=143+Math.floor(j/6)*65,offset=movie?Math.sin(progress*25+j)*(mode==='warm'?2+input/12:2):0;body+=ball(x+offset,y);}for(let [y,value,name,color]of[[295,r.kinetic,'Kinetic',coral],[359,r.potential,'Potential',mint]]){body+=T(98,y-17,name,19)+B(165,y-38,320,38,'#173247')+`<rect x="167" y="${y-36}" width="${316*(revealed||movie?value:100)/200}" height="34" rx="8" fill="${color}"/>`+T(322,y-11,revealed||movie?fmt(value)+' J':'Predict energy part',18,'#faf5ed');}
body+=T(280,416,revealed||movie?'Total '+fmt(r.total)+' J · input '+fmt(input)+' J':'Starting KE100 J + PE100 J; input '+b+' J',21)+T(280,456,'Account illustrates contributions; particle motion/energies not calibrated',14)+T(280,477,'Temperature reflects average KE, not the total internal-energy account',13);
return thermalSVG(body,`${mode==='warm'?'Single-phase warming':'Melting at constant temperature'}, input${fmt(input)}J. ${revealed||movie?`Kinetic${fmt(r.kinetic)}J, potential${fmt(r.potential)}J, total${fmt(r.total)}J; temperature${r.temperature}.`:'Output contribution hidden until reveal; starting kinetic100J and potential100J.'} Twelve fixed-size markers; no molecular energy calibration.`);}
export function latentFigure({a='fusion',b='0.1',progress=0,movie=false,revealed=true}={}){let r=experimentResult('latent',a,b),p=movie?progress:1,n=Math.floor(p*12),body=T(280,29,'State changes at a fixed temperature',23)+T(280,65,a==='fusion'?'Fusion · solid → liquid':'Vaporisation · liquid → gas',22)+B(65,102,430,215,'#1c394c');for(let j=0;j<12;j++){let changed=j<n,x=changed?95+(j*57%365):165+(j%4)*60,y=changed?130+(j*43%150):178+Math.floor(j/4)*45;if(a==='fusion'&&changed)y=234+(j%3)*25;body+=ball(x+(movie?3*Math.sin(progress*14+j):0),y,11);}
body+=T(280,348,'Temperature '+r.temperature+'°C · mass '+r.mass+' kg',21)+T(280,382,'L = '+r.L+' J/kg · E = mL',22)+T(280,419,revealed||movie?fmt(r.value*(movie?p:1))+' / '+r.value+' J transferred':'Predict energy needed / J',23)+T(280,456,'Original toy material, not water · changing phase fraction, fixed particle size',13)+T(280,477,'No temperature rise during this ideal phase-change interval',14);
return thermalSVG(body,`${a} of${r.mass}kg toy material at${r.temperature}degrees Celsius. L${r.L}J/kg. ${revealed||movie?'Required energy'+r.value+'J; current input'+fmt(r.value*(movie?p:1))+'J.':'Required energy concealed until reveal.'} Phase fraction illustrated by twelve identical-size markers, not literal molecular count or actual trajectories.`);}
export function curveMovieTime(p){let i=Math.min(4,Math.floor(p*5)),f=p===1?1:p*5-i,ts=[0,10,20,80,100,120];return ts[i]+(ts[i+1]-ts[i])*f;}
const points=[[0,10],[10,20],[20,20],[80,80],[100,80],[120,100]],gx=t=>70+t*3.5,gy=T=>365-T*2.65;
export function curveFigure({a='heat',b='15',progress=0,movie=false,revealed=true,state='0'}={}){let t=movie?curveMovieTime(progress):+b,r=heatingAt(t,a),pts=a==='heat'?points:points.map(([x,y])=>[120-x,y]).reverse(),path=pts.map(([x,y],i)=>(i?'L':'M')+gx(x)+' '+gy(y)).join(''),body=T(280,28,a==='heat'?'Heating · constant1000 W input':'Cooling · constant1000 W removed',23)+T(280,60,'1 kg toy material · fixed pressure · no losses',17)+L(70,85,70,365)+L(70,365,505,365);
for(let y of[0,20,40,60,80,100])body+=L(64,gy(y),490,gy(y),'#65818f',1)+T(40,gy(y)+5,y,14);for(let x of[0,20,40,60,80,100,120])body+=L(gx(x),365,gx(x),371)+T(gx(x),390,x,14);
body+=T(280,415,'Elapsed time / s',18)+T(128,87,'Temperature / °C',15)+`<path d="${path}" fill="none" stroke="${coral}" stroke-width="4"/>`+L(gx(t),365,gx(t),gy(r.temperature),mint,2)+ball(gx(t),gy(r.temperature),7)+T(280,447,revealed||movie?fmt(t)+' s · '+fmt(r.temperature)+'°C · '+r.phase:'Read the temperature at '+b+' s',21)+T(280,475,'20°C fusion plateau · 80°C vaporisation plateau · invented material',13);
return thermalSVG(body,`${a==='heat'?'Heating':'Cooling'} temperature-time curve for1kg toy substance,1000W transfer. Axes time0–120s and temperature0–100degrees Celsius. ${revealed||movie?'Cursor'+fmt(t)+'s, temperature'+fmt(r.temperature)+'degrees, '+r.phase+'.':'Cursor time'+b+'s; read temperature from curve.'} Plateaus at20 and80degrees; energy still transferred there. c1000J/kg/degree; fusion10000J/kg; vaporisation20000J/kg.`);}
const reflect=(s,n)=>{let q=((s%(2*n))+2*n)%(2*n);return q<=n?q:2*n-q;};
function gasParticles(x,y,w,h,p,speed=1){let body='';for(let j=0;j<16;j++){let vx=(j%2?-1:1)*(25+j*4),vy=(j%3?-1:1)*(31+j*3),xx=x+12+reflect(j*47+p*vx*speed,w-24),yy=y+12+reflect(j*39+p*vy*speed,h-24);body+=ball(xx,yy,8);if(xx<x+23)body+=arrow(x,y+h/2,x-24,y+h/2,mint);if(xx>x+w-23)body+=arrow(x+w,y+h/2,x+w+24,y+h/2,mint);if(yy<y+23)body+=arrow(x+w/2,y,x+w/2,y-22,mint);if(yy>y+h-23)body+=arrow(x+w/2,y+h,x+w/2,y+h+22,mint);}return body;}
export function gasFigure({a='20',b='warm',progress=0,movie=false,revealed=true}={}){let initial=+a,final=initial+(b==='warm'?10:-10),fraction=movie?progress:1,temp=initial+(final-initial)*fraction,speed=.7+temp/100,body=T(280,29,'Fixed mass · fixed volume · wall impacts',23)+B(80,112,400,231,'#1a374b')+gasParticles(80,112,400,231,movie?progress*12:1,speed)+T(280,79,'Temperature '+fmt(temp)+'°C',22)+T(280,383,'Initial '+initial+'°C → final '+final+'°C',22)+T(280,422,revealed||movie?(b==='warm'?'Average KE rises · pressure rises':'Average KE falls · pressure falls'):'Predict KE and pressure response',21)+T(280,459,'16 fixed-size markers · symbolic speeds/impacts, not calibrated readings',13)+T(280,479,'Qualitative pressure relationship · no Celsius pressure-ratio calculation',13);
return thermalSVG(body,`Rigid sealed box,16 same-size molecule markers. Temperature${fmt(temp)}degrees, initial${initial}, final${final}. ${revealed||movie?(b==='warm'?'Average KE and pressure rise.':'Average KE and pressure fall.'):'Pressure/KE response concealed until prediction.'} Varied illustrative reflected trajectories, no real collision statistics or pressure calibration; volume and particle count fixed.`);}
export function compressionFigure({a='0.002',b='100000',progress=0,movie=false,revealed=true}={}){let V=movie?.004-.002*progress:+a,p1=+b,p=compressedPressure(p1,V),w=380*V/.008,x=80,y=115,body=T(280,29,'Fixed mass · temperature maintained constant',23)+B(x,y,380,210,'#162f42')+B(x,y,w,210,'#25475b')+gasParticles(x,y,w,210,movie?progress*10:1,1)+L(x+w,y-12,x+w,y+222,coral,8)+(V>.004?arrow(x+w-34,y+105,x+w+20,y+105):arrow(500,y+105,x+w+10,y+105))+T(280,78,'Piston · reservoir maintains temperature',20)+T(280,371,'Initial '+p1+' Pa · 0.004 m³',21)+T(280,408,'Final volume '+fmt(V)+' m³',21)+T(280,444,revealed||movie?'p = '+fmt(p)+' Pa · pV = '+p1*.004+' Pa·m³':'Predict final absolute pressure / Pa',22)+T(280,477,'No leaks/friction · particle speed scale fixed · not insulated rapid compression',13);
return thermalSVG(body,`Maintained-temperature compression, initial${p1}Pa and0.004m cubed, final volume${fmt(V)}m cubed. ${revealed||movie?'Final pressure'+fmt(p)+'Pa; pV'+p1*.004+'Pa m cubed.':'Pressure output hidden until reveal.'} Sixteen same-size markers retained; speed scale fixed. Wall forces normal to surface; moving piston symbolic, reservoir removes compression energy.`);}
export function workFigure({progress=0,movie=false,state='0'}={}){let p=movie?progress:1,w=380-150*p,temp=20+15*p,body=T(280,29,'Higher · work can warm an enclosed gas',23)+B(70,110,390,212,'#162f42')+B(70,110,w,212,'#25475b')+gasParticles(70,110,w,212,p*11,1+p*.7)+L(70+w,98,70+w,335,coral,8)+arrow(510,215,80+w,215)+T(280,79,'Rapid approximately insulated compression',19)+T(280,367,'Force does work → internal energy increases',22)+T(280,407,'Temperature can rise',25,coral)+T(280,446,'No pV-constant calculation applied to this warming case',18)+T(280,477,'Qualitative response · no adiabatic law, real temperature or friction calibration',12);
return thermalSVG(body,'Higher separate Physics: force moves a piston and transfers energy into enclosed gas; internal energy and temperature can increase in rapid approximately insulated compression. Sixteen markers retained; faster motion qualitative, no numerical pressure/temperature/adiabatic equation. Contrasts with maintained-temperature pV comparison.');}
export function thermalFigure(o={}){if(o.concealed)return thermalSVG(T(280,235,'Predict, then reveal evidence',24),'Evidence concealed until prediction');let k=(o.kind||'internal').replace(/-(model|data|sequence)$/,'');if(k==='internal')return internalFigure({...o,a:o.a||(o.context==='comparison'&&String(o.state)==='2'?'melt':'warm')});if(k==='latent')return latentFigure(o);if(k==='curves')return curveFigure({...o,a:o.a||(String(o.state)==='2'?'cool':'heat'),b:o.b||(o.context==='comparison'?(String(o.state)==='1'?'50':String(o.state)==='2'?'30':'15'):'15')});if(k==='gas')return gasFigure(o);if(k==='work')return workFigure(o);return compressionFigure(o);}
